/** 
 * java.lang.boolean containedIn(java.awt.geom.Rectangle2D, java.util.Collection) Function to test if the given 2D rectangle is contained in any of the given shapes in the collection.
 * @param java.awt.geom.Rectangle2D r
 * @param java.util.Collection      shapes
 */
public static boolean containedIn(Rectangle2D r,Collection shapes){
  Iterator iter=shapes.iterator();
  while (iter.hasNext()) {
    Shape item=(Shape)iter.next();
    if (item.contains(r)) {
      return true;
    }
  }
  return false;
}
